pub(super) fn contains_arabic_script(text: &str) -> bool {
    text.chars().any(|ch| {
        (0x0600..=0x06FF).contains(&(ch as u32)) || (0x0750..=0x077F).contains(&(ch as u32))
    })
}

pub(super) fn has_trailing_punctuation_joiners(text: &str) -> bool {
    text.chars()
        .next_back()
        .map(|ch| matches!(ch, ',' | ':' | ';'))
        .unwrap_or(false)
}
